// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address candidateOwner) public {
        vm.assume(candidateOwner != address(0));

        vm.prank(address(this));
        bool ok;
        try c.setOwner(candidateOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.owner() == candidateOwner);
    }
}
